import { Stack, Typography, Paper } from "@mui/material";
import LoginButton from "./LoginButton";

export default function LoginPage() {
  return (
    <Stack
      sx={{
        height: "100vh",                // full viewport
        justifyContent: "center",       // vertical centering
        alignItems: "center",           // horizontal centering
        bgcolor: "#FFE4C4",             // soft peach background
      }}
    >
      <Paper
        elevation={4}                   // subtle shadow
        sx={{
          p: { xs: 4, sm: 6 },          // padding
          borderRadius: 4,              // rounded corners
          border: "2px solid #ccc",     // subtle border
          bgcolor: "white",             // card background color
          minWidth: { xs: "90%", sm: "400px", md: "500px" },
          textAlign: "center",
        }}
      >
        <Typography
          variant="h2"
          component="h2"
          sx={{ mb: { xs: 4, sm: 6 }, color: "#000" }} // black text
        >
          Welcome to ChefGPT!
        </Typography>

        <Typography
          variant="h4"
          sx={{ mb: { xs: 3, sm: 4 }, color: "#000" }} // black text
        >
          Please Sign In
        </Typography>

        <LoginButton
          sx={{
            width: { xs: "100%", sm: "60%" },
            fontSize: { xs: "1rem", sm: "1.25rem" },
            bgcolor: "#fff",      // white button
            color: "#000",        // black text
            "&:hover": { bgcolor: "#f0f0f0" }, // subtle hover
          }}
        />
      </Paper>
    </Stack>
  );
}
